'use strict';
/**
 * The CONNECTION-TEST reason classifier, as a corpus generated by RUNNING the
 * live implementation.
 *
 * `POST /api/routers/test` in `src/index.js` turns a failed dial into the
 * sentence the router modal shows under the Test button. Somebody presses that
 * button because something is not working, so "Connection failed" tells them
 * nothing they did not already know: each branch names the thing to go and
 * check, and the wording is the feature.
 *
 * ---- THIS IS NOT `classifyError.js`, AND THE SENTENCES DIFFER --------------
 *
 * `tools/classify-error-cases.js` pins the OTHER classifier — the one behind the
 * Routers page's offline reason (#92). The two look alike and are not: this one
 * says "Connection refused — check host and port", that one says "Connection
 * refused — is RouterOS reachable at HOST?". Porting one and reusing it for both
 * would change what the modal says.
 *
 * They are a SECOND COPY OF ONE DECISION, which is what let them drift apart in
 * the first place (see below). Collapsing them is the real fix; upstream has
 * deliberately deferred it to after the cutover, because it rewords several
 * other messages — `classifyError.js` embeds the host and user where the inline
 * one does not — and the JS wording is this port's oracle in the meantime.
 * Recorded in the live repo's `port_drift_notes.md`, Cutover section.
 *
 * ---- WHY IT IS LIFTED RATHER THAN RETYPED ---------------------------------
 *
 * The classifier is inline in the route — fourteen lines of regex chained by
 * `else if` — so there is no module to require, and the route needs a live
 * server stack to reach. It had therefore never been EXECUTED in a test on
 * either side, only source-scanned. It is SLICED out of the file by content
 * anchors and evaluated in a `vm`; two defects fell out of the first run.
 *
 * Everything that matters about it is invisible in the text: the ORDER (a
 * message holding both "certificate" and "authentication" gets the certificate
 * sentence), the CASE SENSITIVITY (`/ECONNREFUSED/` has no `i`, while
 * `/timed out/i` beside it does), and which errors fall through to be sanitised.
 * A retyped copy agrees with the original on the cases someone thought of.
 *
 * ---- THE ONE THING THAT CANNOT BE PORTED LITERALLY ------------------------
 *
 * Same problem `classify-error-cases.js` has, and the same answer. The live
 * matcher reads NODE's error shapes — `ECONNREFUSED`, `ENOTFOUND`, an `.errno`
 * of `CANTLOGIN`, a `RosException` name. Go's errors carry none of them.
 *
 * So the contract is condition -> sentence. Each case names the condition, the
 * input the LIVE side needs to reach that branch, and the input a GO error would
 * carry for the same condition. A case with `null` for the third has no Go
 * analogue: it exists to pin a property of the live REGEXES (case sensitivity,
 * branch order) and is checked here rather than in Go.
 *
 * ---- THE TWO DEFECTS THIS CORPUS FOUND, BOTH NOW FIXED UPSTREAM -----------
 *
 * 1. The last branch tested `body.tls`, the RAW request field, where every other
 *    decision in the route used `testTls`, the coerced one
 *    (`body.tls !== false && body.tls !== 'false'`). They disagree BOTH ways:
 *
 *      absent   coerced is TRUE, TLS defaults on, but the raw field is falsy, so
 *               a connection over api-ssl was blamed on the plain `api` service.
 *      "false"  coerced is FALSE, but a non-empty string is truthy, so a plain
 *               connection was blamed on a handshake that never happened.
 *
 * 2. RouterOS's own words for a rejected login — "invalid user name or
 *    password" — matched NONE of the previous alternatives: no "authentication",
 *    no "login" ("log in" has a space), and the router says "user name" as two
 *    words where the pattern wanted one. So the commonest failure of the button
 *    fell through to the raw driver message unless the errno was CANTLOGIN.
 *    `classifyError.js` caught the same string, because ITS list includes
 *    `invalid user` — the drift, exactly.
 *
 * Both fixed in f4ade9e, and this corpus FOLLOWS rather than freezing them: the
 * slice guard below fails if `body.tls` comes back, and the alternative-set
 * ledger fails if the two classifiers' lists diverge again. Pinning the rule,
 * not the symptom.
 *
 *   MIKRODASH_SRC=../MikroDash node tools/test-reason-cases.js          # write
 *   MIKRODASH_SRC=../MikroDash node tools/test-reason-cases.js --check  # fail if stale
 */

const fs = require('node:fs');
const path = require('node:path');
const vm = require('node:vm');

const ROOT = path.join(__dirname, '..');
const LIVE = path.resolve(process.env.MIKRODASH_SRC || path.join(ROOT, '..', 'MikroDash'));
const OUT = path.join(ROOT, 'testdata', 'test-reason-cases.json');

// ---- Slice the classifier out of the route ---------------------------------
// Anchored on CONTENT, never on line numbers: `index.js` is ~7,200 lines and
// everything above this moves. A lost anchor throws, rather than emitting a
// corpus built from whatever happened to be at those lines.
const indexSrc = fs.readFileSync(path.join(LIVE, 'src', 'index.js'), 'utf8');
const lines = indexSrc.split('\n');
const start = lines.findIndex((l) => l.includes("testRos.on('connectionError'"));
if (start < 0) throw new Error('anchor lost: the connectionError handler on testRos');
const end = lines.findIndex((l, i) => i > start && l.includes('No classifier matched'));
if (end < 0) throw new Error('anchor lost: the "No classifier matched" comment');
const bodyStart = lines.findIndex((l, i) => i > start && l.includes('const msg = e && e.message'));
if (bodyStart < 0 || bodyStart > end) throw new Error('anchor lost: `const msg =` inside the handler');
const slice = lines.slice(bodyStart, end).join('\n');

// A classifier that no longer branches is not a classifier. Six `else if`s were
// there when this was written; a slice that lost them would still evaluate, and
// would agree with an empty Go function on every case.
const branches = (slice.match(/else if \(/g) || []).length;
if (branches < 6) {
  throw new Error(`slice has ${branches} else-if branches, expected >= 6 - the anchors drifted`);
}

// A LEDGER OVER THE FIX, not over today's strings. The last branch must read the
// COERCED flag; `body.tls` returning there is defect 1 coming back, and it would
// come back SILENTLY — both spellings evaluate and both produce a sentence, so
// no output distinguishes them on the inputs where the two happen to agree.
//
// COMMENTS STRIPPED FIRST. The fix's own comment says "testTls, NOT body.tls",
// which is the right thing for it to say and made the first version of this
// guard fire on the very commit it was written to protect.
const sliceCode = slice.replace(/\/\/[^\n]*/g, '');
if (/\bbody\.tls\b/.test(sliceCode)) {
  throw new Error('the classifier reads body.tls again - the raw field disagrees with testTls in '
    + 'both directions (see the header). Fixed upstream in f4ade9e; this generator will not '
    + 'encode the regression.');
}
if (!/\btestTls\b/.test(sliceCode)) {
  throw new Error('the classifier no longer reads testTls; find what replaced it before '
    + 'regenerating - this corpus supplies that value as the slice\'s second argument');
}

// ---- The drift ledger ------------------------------------------------------
// The rule rather than the symptom. `classifyError.js` is the CANONICAL
// classifier — its own header records that it was extracted from inline
// precisely so it would be reachable everywhere — and the route kept a duplicate
// anyway. Defect 2 was that duplicate falling one pattern behind for about a
// year.
//
// So this compares the ALTERNATIVE SETS and fails when the canonical one gains a
// pattern the inline copy lacks. It keeps working when either side legitimately
// grows, and catches the NEXT drift rather than the one already fixed.
//
// One direction only, deliberately: the inline copy carrying an extra pattern is
// not a defect (it classifies more, and the canonical one is free to be
// narrower). The canonical copy carrying one the inline lacks is a message the
// modal will not show.
const canonicalSrc = fs.readFileSync(path.join(LIVE, 'src', 'routeros', 'classifyError.js'), 'utf8');
const authPatterns = (src, label) => {
  // THE TWO COPIES ARE SHAPED DIFFERENTLY, which is worth knowing rather than
  // working around silently. The inline one is a single long line ending in
  // `reason = '...'`; `classifyError.js` puts the condition on one line and the
  // assignment on the next. So this finds the assignment and walks BACK to the
  // nearest condition — at most a few lines, because an `else if` cannot be far
  // from what it assigns.
  const src_ = src.split('\n');
  const at = src_.findIndex((l) => /Authentication failed/.test(l));
  if (at < 0) {
    // Not a soft skip. An unfindable branch means the shape changed, and a
    // ledger that quietly compares nothing is worse than no ledger.
    throw new Error(`${label}: cannot find the authentication branch - the ledger has gone blind`);
  }
  for (let i = at; i >= Math.max(0, at - 4); i--) {
    if (/test\(/.test(src_[i])) {
      return new Set((src_[i].match(/\/[^/\n]+\/i?/g) || []).map((r) => r.replace(/^\/|\/i?$/g, '')));
    }
  }
  throw new Error(`${label}: found the authentication sentence but no condition above it - `
    + 'the ledger has gone blind');
};
const canonical = authPatterns(canonicalSrc, 'classifyError.js');
const inline = authPatterns(slice, 'the inline route classifier');
const missing = [...canonical].filter((p) => !inline.has(p));
if (missing.length) {
  throw new Error('THE TWO CLASSIFIERS HAVE DRIFTED AGAIN. classifyError.js matches '
    + missing.map((m) => `/${m}/`).join(', ') + ' on a rejected login and the inline copy in '
    + 'POST /api/routers/test does not, so the modal shows the raw driver message where the '
    + 'Routers page shows a sentence. Edit one, edit both - or collapse them, which is the '
    + 'real fix and is recorded for after the cutover.');
}

const UNMATCHED = ' unmatched '; // a sentinel no real sentence can be
// `testTls` is the COERCED flag, so the classifier takes a plain boolean — the
// raw request field and its JavaScript truthiness are the route's business (and
// internal/routers/endpoint.go's), not this function's.
const classify = vm.runInNewContext(
  `(function (e, testTls) {\n${slice}\n  return reason === msg ? ${JSON.stringify(UNMATCHED)} : reason; })`,
  Object.create(null),
  { filename: 'index.js#connectionError' },
);

/** An error shaped the way node's driver delivers one. */
function nodeErr(message, extra) {
  const e = new Error(message);
  return Object.assign(e, extra || {});
}

// The fourth column is `testTls`, the COERCED flag — a plain boolean since
// f4ade9e. It reaches only the last branch, so every case outside it passes the
// value the route computes for an absent field, which is TRUE.
const TLS_DEFAULT = true;

// condition                 what the LIVE side sees                            what a GO error says                                       testTls
const CASES = [
  ['refused',                nodeErr('connect ECONNREFUSED 198.51.100.5:8729'), 'dial tcp 198.51.100.5:8729: connect: connection refused',  TLS_DEFAULT],
  ['timed out',              nodeErr('connect ETIMEDOUT 198.51.100.5:8729'),    'dial tcp 198.51.100.5:8729: i/o timeout',                  TLS_DEFAULT],
  ['timed out, worded',      nodeErr('socket timed out after 8000ms'),          'read tcp 198.51.100.5:8729: i/o timeout',                  TLS_DEFAULT],
  ['host not found',         nodeErr('getaddrinfo ENOTFOUND rtr.invalid'),      'dial tcp: lookup rtr.invalid: no such host',               TLS_DEFAULT],
  ['reset',                  nodeErr('read ECONNRESET'),                        'read tcp 198.51.100.5:8729: connection reset by peer',     TLS_DEFAULT],
  ['certificate',            nodeErr('self signed certificate in certificate chain'),
                             'tls: failed to verify certificate: x509: certificate signed by unknown authority',                            TLS_DEFAULT],
  // A REFUSED LOGIN, by the route the live side reaches it: its errno.
  ['auth by errno',          nodeErr('refused by device', { errno: 'CANTLOGIN' }), 'from RouterOS device: cannot log in',                    TLS_DEFAULT],
  // AND BY ITS TEXT, which is the fix in f4ade9e. Before it, this exact string —
  // RouterOS's own — fell through to the raw driver message.
  ['auth, RouterOS wording', nodeErr('invalid user name or password'),
                             'from RouterOS device: invalid user name or password',                                                         TLS_DEFAULT],
  ['nothing matches',        nodeErr('the router said something unexpected'),   'the router said something unexpected',                     TLS_DEFAULT],
  // A TRAP CARRYING THE DEVICE'S OWN WORDS, capitalised. RouterOS trap text is
  // arbitrary device output and this port folds it into `routeros: <message>`,
  // so the matcher lowercases before comparing. Without a case like this the
  // lowercasing is untested and deleting it looks free.
  ['auth, capitalised device text', nodeErr('Cannot login'), { goTrap: true, message: 'Cannot log in' }, TLS_DEFAULT],
  // A TLS HANDSHAKE FAILURE is what node reports as a RosException during
  // connect, and it is the condition the last branch's first arm describes. Go
  // says so in as many words when api-ssl is off and 8729 answers as plain api.
  ['tls handshake',          nodeErr('RosException', { errno: '' }),            'tls: first record does not look like a TLS handshake',      true],

  // NODE'S `RosException` IS THE PORT'S `*Trap` — both mean "the device answered
  // with an error" rather than "the socket failed", which is what the branch
  // turns on. `goTrap` tells the Go test to build one; there is no message to
  // match, and inventing a Go spelling for a node type is what the whole
  // condition-not-regex arrangement exists to avoid.
  //
  // A Trap carries no errno, so these use `errno: ''`. The live branch then
  // omits its `[errno]` bracket and the two sides agree exactly, rather than the
  // port having to fabricate a number.
  //
  // TWO CASES, because `testTls` is a boolean now. It took four while the branch
  // read the raw field, and the pair that mattered — absent, and the string
  // "false" — are exactly the two the fix removed.
  ['ros exception, tls on',  nodeErr('RosException', { errno: '' }), { goTrap: true }, true],
  ['ros exception, tls off', nodeErr('RosException', { errno: '' }), { goTrap: true }, false],

  // ---- LIVE-ONLY: properties of the REGEXES, with no Go analogue -----------
  // Ordering. Each matches two branches; the earlier must win. Go's messages
  // never carry two conditions at once, so there is nothing to feed the port —
  // `internal/routeros/testreason_test.go` checks the chain at the source
  // instead, and says why.
  ['order: certificate beats authentication', nodeErr('certificate authentication problem'), null, TLS_DEFAULT],
  ['order: ECONNREFUSED beats timed out',     nodeErr('ECONNREFUSED after it timed out'),    null, TLS_DEFAULT],
  ['order: login beats RosException',         nodeErr('RosException: login failure'),        null, TLS_DEFAULT],
  // Case sensitivity. The four transport codes have no `i`; the prose beside
  // them does. A lowercased code falls through to the sanitiser.
  ['case: lowercase econnrefused falls through', nodeErr('connect econnrefused 198.51.100.5'), null, TLS_DEFAULT],
  ['case: lowercase enotfound falls through',    nodeErr('enotfound rtr.invalid'),             null, TLS_DEFAULT],
  ['case: prose "connection reset" falls through', nodeErr('the connection was reset'),        null, TLS_DEFAULT],
  ['case: SHOUTED prose timeout still matches',  nodeErr('SOCKET TIMED OUT'),                  null, TLS_DEFAULT],
  ['case: capitalised Certificate still matches', nodeErr('Certificate has expired'),          null, TLS_DEFAULT],
  // The alternation whose halves are reachable only through prose no driver this
  // port uses produces.
  ['alt: username .* invalid', nodeErr('the username supplied is invalid'), null, TLS_DEFAULT],
  ['alt: password .* invalid', nodeErr('the password supplied is invalid'), null, TLS_DEFAULT],
  ['alt: wrong password',      nodeErr('wrong password for that user'),     null, TLS_DEFAULT],
];

const out = CASES.map(([condition, live, go, testTls]) => {
  const reason = classify(live, testTls);
  return {
    condition,
    // What the live classifier was actually given, recorded so a reader can see
    // why a case landed where it did without re-running the generator.
    liveMessage: live.message,
    liveErrno: live.errno || '',
    liveName: live.name === 'Error' ? '' : live.name || '',
    // The COERCED flag. There is no raw field here any more: `endpointTLS` in
    // internal/routers/endpoint.go owns that coercion and
    // tools/same-endpoint-cases.js pins it, so encoding it twice would give the
    // port two places to disagree with itself.
    tls: testTls,
    // The Go input. `goMessage` is a string a Go dial would produce; `goTrap`
    // says to build a *routeros.Trap instead; neither means live-only.
    goMessage: typeof go === 'string' ? go : null,
    goTrap: !!(go && go.goTrap),
    // The text a *Trap carries, when the case is about that text rather than
    // about the type. Empty means "any message matching no branch", which is
    // what proves the TYPE reached the last branch.
    goTrapMessage: (go && go.message) || '',
    matched: reason !== UNMATCHED,
    reason: reason === UNMATCHED ? '' : reason,
  };
});

// ---- Believability ---------------------------------------------------------
// Every assertion here is about what the LIVE side produced, not about what the
// port does with it. The failure this guards against is silent: a broken slice
// returns one answer for every input, and a Go test comparing against it passes.
const byCond = Object.fromEntries(out.map((c) => [c.condition, c]));
const need = (k) => {
  if (!byCond[k]) throw new Error(`a believability check names a case that is gone: ${k}`);
  return byCond[k];
};
const distinct = new Set(out.filter((c) => c.matched).map((c) => c.reason));
if (distinct.size < 8) {
  throw new Error(`only ${distinct.size} distinct sentences; the classifier collapsed`);
}
if (!out.some((c) => !c.matched)) {
  throw new Error('nothing fell through to the sanitiser - the corpus cannot show the default');
}
// Order, stated as the sentence rather than as an index, so reordering CASES
// cannot quietly satisfy it.
if (!/certificate/i.test(need('order: certificate beats authentication').reason)) {
  throw new Error('branch order lost: authentication now wins over certificate');
}
if (!/refused/i.test(need('order: ECONNREFUSED beats timed out').reason)) {
  throw new Error('branch order lost: the timeout branch now wins over ECONNREFUSED');
}
if (!/Authentication/.test(need('order: login beats RosException').reason)) {
  throw new Error('branch order lost: RosException now wins over the login branch');
}
// Case sensitivity, both halves: the codes are exact, the prose is not.
for (const k of ['case: lowercase econnrefused falls through',
  'case: lowercase enotfound falls through',
  'case: prose "connection reset" falls through']) {
  if (need(k).matched) throw new Error(`the transport codes became case-insensitive upstream: ${k}`);
}
if (!need('case: SHOUTED prose timeout still matches').matched) {
  throw new Error('the /timed out/i branch lost its case-insensitive flag');
}
if (!need('case: capitalised Certificate still matches').matched) {
  throw new Error('the /certificate/i branch lost its case-insensitive flag');
}
// DEFECT 2, asserted FIXED rather than asserted present. It was the commonest
// failure of this button, and a regression would be silent in exactly the way
// the original was.
if (!/Authentication failed/.test(need('auth, RouterOS wording').reason)) {
  throw new Error("RouterOS's own login wording fell through again - f4ade9e added `invalid user` "
    + 'to the inline branch; if it went away, the drift ledger above should have caught it first');
}
// The last branch's two arms genuinely differ, which is what makes the pair
// discriminating rather than decorative.
if (need('ros exception, tls on').reason === need('ros exception, tls off').reason) {
  throw new Error('the RosException arms collapsed onto one sentence');
}
if (!/api-ssl/.test(need('ros exception, tls on').reason)) {
  throw new Error('tls ON no longer names api-ssl - the branch stopped describing the connection '
    + 'that was actually attempted, which is what f4ade9e fixed');
}
if (!/api service/.test(need('ros exception, tls off').reason)) {
  throw new Error('tls OFF no longer names the plain api service');
}
// Nothing here may carry a credential. The corpus is error TEXT, which is
// exactly where a driver leaks one, so it is checked rather than assumed.
//
// It looks for a credential CARRIER, not for the word: one live branch is
// `/wrong password/i` and the case reaching it has to say "password" out loud.
// Banning the word would have deleted the only coverage of an alternative, which
// is how a scanner ends up protecting nothing.
const blob = JSON.stringify(out).toLowerCase();
for (const re of [/passw[a-z]*\s*[:=]\s*\S/, /\bpass\s*[:=]\s*\S/, /secret\s*[:=]\s*\S/,
  /bearer\s+\S/, /api[-_]?key/, /token\s*[:=]\s*\S/, /-----begin/]) {
  if (re.test(blob)) throw new Error(`corpus matches ${re} - a credential carrier, not prose`);
}

const json = JSON.stringify({
  generated_from: 'src/index.js POST /api/routers/test (inline connectionError handler)',
  cases: out,
}, null, 2) + '\n';

if (process.argv.includes('--check')) {
  const have = fs.existsSync(OUT) ? fs.readFileSync(OUT, 'utf8') : '';
  if (have !== json) {
    console.error('STALE: testdata/test-reason-cases.json - re-run tools/test-reason-cases.js');
    process.exit(1);
  }
  console.log(`test-reason-cases: up to date (${out.length} cases, ${distinct.size} sentences)`);
} else {
  fs.writeFileSync(OUT, json);
  const goCases = out.filter((c) => c.goMessage || c.goTrap).length;
  console.log(`wrote ${OUT} (${out.length} cases, ${goCases} with a Go input, ${distinct.size} distinct sentences)`);
}
